// Flatten monday item into a friendly object.
// Prefer values pushed in the webhook body by the caller (e.g. the
// /api/webhooks/slack-blog route on Vercel). Fall back to the monday
// fetch for callers that only send pulseId. Sidesteps the eventual-
// consistency race that produced the 'title undefined' draft for pulse
// 2714465661 on 2026-05-24.
const wh = $('Webhook: /marketa-draft').first().json.body || {};
const item = $input.first().json.data?.items?.[0];
const col = (id) => item?.column_values?.find(c => c.id === id);
const text = (c) => c?.text?.trim() || '';
const pulseId = wh.pulseId;
if (!pulseId) throw new Error('pulseId missing from webhook body');
return [{
  json: {
    pulseId: String(pulseId),
    title: wh.title || item?.name || '',
    brief: wh.brief || text(col('long_text_mm3grk84')),
    target_keyword: wh.target_keyword || text(col('text_mm3gzj88')),
    industry: wh.industry || text(col('dropdown_mm3gb7wm')) || 'general'
  }
}];

// Build the Claude prompt: voice guide + brief + retrieved chunks.
const meta = $('Normalize item').first().json;
const chunks = $('Supabase: retrieve chunks').all().map(i => i.json);
const voice = $('Fetch voice guide').first()?.json?.result || '(no voice guide)';
const context = chunks.map((c, i) => `--- Source ${i+1} (id: ${c.source_id}) ---\n${c.body}`).join('\n\n');
return [{
  json: {
    ...meta,
    voice,
    context,
    source_ids: chunks.map(c => c.source_id)
  }
}];

const draft = $input.first().json.content?.[0]?.text || '';
const meta = $('Normalize item').first().json;
return [{ json: { pulseId: meta.pulseId, draft } }];

